    # colored edge marker, with the original marker changed to 4.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color in (0, 3, 5, 8):
                continue
            for dr, dc in ((0, -1), (0, 1), (-1, 0), (1, 0)):
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    rr += dr
                    cc += dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] not in (bg, color):
                    for pr, pc in _path(r, c, rr, cc):
                        out[pr][pc] = color
                    out[r][c] = 4
                    break
    return out

def _path(r, c, rr, cc):
    dr = 0 if rr == r else (1 if rr > r else -1)
    dc = 0 if cc == c else (1 if cc > c else -1)
    while (r, c) != (rr, cc):
        r += dr
        c += dc
        yield r, c
